B.bhG=new A.bT(B.bjy,["Mitra tidak ditemukan.","Mitra belum bisa menerima pesanan.","Mitra sedang tutup. Pilih mitra lain atau coba nanti.","Pilih alamat pengantaran terlebih dahulu.","Alamat tidak ditemukan di akunmu.","Alamat belum memiliki titik lokasi.","Alamatmu di luar jangkauan mitra.","Jadwal penjemputan tidak tersedia.","Layanan yang dipilih tidak tersedia.","Pesanan tidak ditemukan.",u.W,"Alasan pembatalan wajib diisi.","Pesanan tidak bisa diproses pada status ini.","Perubahan status pesanan tidak diizinkan.","PIN konfirmasi tidak sesuai.",u.r,"PIN konfirmasi belum dibuat untuk pesanan ini.","Pembayaran untuk pesanan ini belum tersedia.","Lampirkan bukti pembayaran terlebih dahulu.","Pembayaran diperlukan sebelum mitra dapat menerima pesanan.","Pesanan ini sudah dibayar.","Settlement tidak ditemukan.","Settlement ini sudah dibayar.","Settlement ini gagal dan tidak bisa dicairkan.","Pencairan sudah diajukan. Menunggu proses admin.","Periode settlement belum ditutup.","Tidak ada dana yang bisa dicairkan.","Atur rekening pencairan terlebih dahulu.","Bank belum didukung.","Nomor rekening tidak valid.","Nama pemilik rekening tidak valid.","Total pembayaran tidak valid.","Metode pembayaran ini belum mendukung pembayaran online.","Terlalu banyak percobaan pembayaran. Coba lagi nanti.",u.f,"Pembayaran sedang diproses. Muat ulang pesanan beberapa saat lagi.","Gateway pembayaran tidak merespons. Coba lagi.","Gateway pembayaran tidak tersedia. Coba lagi.","Pembayaran sedang diproses. Coba lagi sebentar.","Kode pembayaran ini dibuat lewat jalur lain. Muat ulang pesanan.","Metode pembayaran tidak cocok dengan kode yang aktif.","Detail pembayaran tidak valid. Coba lagi.","Pembayaran sudah dibuat tetapi belum tersimpan. Coba lagi.","Pembayaran online belum tersedia.","Pembayaran online belum tersedia.",u.f,"Sesi pembayaran tidak valid. Coba lagi.","Sesi pembayaran sudah berakhir. Coba lagi.","Sesi pembayaran tidak valid. Coba lagi.","Total tidak bisa diubah karena pembayaran sudah diterima.","Pembayaran online dikonfirmasi otomatis oleh gateway.","Simulasi pembayaran sedang dimatikan. Gunakan pembayaran online.","Hasil simulasi pembayaran tidak dikenal."],t.li)
B.UC=new A.cu([0,411,1,435,2,819,3,201,4,393,5,401,6,153,7,281,8,305,9,147,10,275,11,291,12,461,13,473,14,921,15,413,16,441,17,825,18,627,19,467,20,915,21,315,22,371,23,951,24,407,25,423,26,807,27,311,28,359,29,615,30,219,31,795,32,867,33,197,34,209,35,785,36,141,37,177,38,561,39,139,40,163,41,547,42,237,43,909,44,945,45,221,46,797,47,881,48,887,49,907,50,931,51,187,52,571,53,955,54,215,55,791,56,839,57,183,58,567,59,711,60,759,61,531,62,655,63,101,64,389,65,105,66,777,67,417,68,801,69,77,70,269,71,89,72,537,73,353,74,609,75,579,76,83,77,751,78,323,79,753,80,485,81,489,82,969,83,317,84,377,85,633,86,303,87,335,88,591,89,987,90,891,91,879,92,245,93,965,94,977,95,189,96,573,97,175,98,559,99,989,100,957,101,983,102,943,103,267,104,75,105,459,106,739,107,235,108,6883],t.KL)
B.amd=new A.fd("Bagaimana mengatur layanan dan harga?","Buka Profil lalu Layanan & Harga. Tambahkan layanan, atur harga per satuan, dan tentukan layanan mana yang aktif. Perubahan harga berlaku untuk pesanan baru, bukan pesanan yang sudah dibuat.")
B.am4=new A.fd("Kapan penghasilan pesanan masuk ke pencairan?","Setiap pesanan yang lunas dicatat sebagai bagian mitra setelah komisi platform dipotong. Bagian itu digabung ke periode settlement; setelah periode ditutup, dana bisa dicairkan ke rekening terdaftar.")
B.am0=new A.fd("Bagaimana mengajukan pencairan?","Pastikan rekening sudah diatur di Profil lalu Payout & Settlement. Buka Detail salah satu settlement, periksa periode dan nominal bersih, lalu pilih Ajukan Pencairan. Status berubah menjadi Diminta dan admin memproses transfer ke rekening yang tercatat.")
B.am9=new A.fd("Berapa komisi platform yang dipotong?","Komisi mengikuti pengaturan kategori layanan dan mitra. Nominal persisnya selalu ditampilkan di rincian settlement, termasuk bagian mitra dan komisi platform untuk setiap pesanan.")
B.amb=new A.fd("Kenapa tombol pencairan tidak aktif?","Pencairan baru bisa diajukan setelah periode settlement berakhir, nominal bersih lebih dari nol, rekening sudah diatur, dan belum ada permintaan pencairan untuk periode itu. Kalau salah satunya belum terpenuhi, tombolnya dinonaktifkan.")
B.am5=new A.fd("Bagaimana menangani pesanan dan komplain?","Pesanan baru dan komplain muncul di Dashboard. Terima atau tolak pesanan sesuai ketersediaan, perbarui status saat proses berjalan, dan tanggapi komplain lewat menu Komplain. Riwayat tindakan tersimpan di detail pesanan.")
B.ben=s([B.amd,B.am4,B.am0,B.am9,B.amb,B.am5],t.vW)
B.ami=new A.C6("Mitra","Panduan singkat operasional mitra: layanan, pesanan, komisi, dan pencairan ke rekeningmu.",B.ben,"Chat Pelanggan","/merchant-chat","Balasan cepat menjaga rating mitra; gunakan chat untuk pertanyaan pesanan yang sedang berjalan.")
B.am6=new A.fd("Bagaimana mengambil task pengantaran?","Buka daftar Task dari beranda. Task yang tersedia bisa diambil, lalu ikuti tombol aksi untuk memulai penjemputan dan pengantaran. Satu task hanya bisa diambil satu kurir.")
B.am3=new A.fd("Apa arti setiap status task?","Task berjalan dari Ditugaskan, Diterima, Dalam Perjalanan, sampai Selesai. Tombol aksi di layar selalu mengikuti status berikutnya, sehingga kamu tidak perlu menebak langkah selanjutnya.")
B.ama=new A.fd("Apakah harus mengunggah bukti pengantaran?","Ya, unggah foto bukti saat menyelesaikan pengantaran. Foto ini menjadi bukti bagi pelanggan dan mitra kalau pesanan sudah diterima di alamat tujuan.")
B.am_=new A.fd("Bagaimana kalau pesanan gagal diantar?","Kalau pelanggan tidak bisa dihubungi atau alamat tidak ditemukan, tandai task sebagai gagal dan tuliskan alasannya. Tim LagiButuh menggunakan alasan ini untuk menindaklanjuti dengan pelanggan.")
B.alX=new A.fd("Bagaimana mengatur status bertugas?","Status bertugas diatur dari beranda kurir. Saat berhenti menerima task, matikan status tersebut agar task baru tidak masuk. Task yang sudah diambil tetap harus diselesaikan.")
B.amg=new A.fd("Bagaimana melihat riwayat dan penghasilan task?","Buka Profil lalu Riwayat Task. Setiap task yang selesai tercatat beserta tanggal dan statusnya, sehingga kamu bisa mencocokkan penghasilan dengan task yang sudah dikerjakan.")
B.b4A=s([B.am6,B.am3,B.ama,B.am_,B.alX,B.amg],t.vW)
B.amj=new A.C6("Kurir","Hal yang paling sering ditanyakan kurir soal pengambilan task, bukti pengantaran, dan status bertugas.",B.b4A,"Chat Pelanggan","/courier-chat","Gunakan chat untuk mengoordinasikan alamat atau waktu pengantaran.")
B.amh=new A.fd("Bagaimana memproses pencairan mitra?","Buka Settlement Merchant lalu filter Diminta. Periksa periode, nominal bersih, dan rekening tujuan, transfer sesuai nominal, lalu pilih Pay Out. Kalau transfer tidak bisa dilakukan, pilih Mark Failed agar mitra bisa mengajukan ulang.")
B.ame=new A.fd("Bagaimana memverifikasi mitra baru?","Di menu Merchant, buka detail mitra yang menunggu verifikasi. Periksa identitas dan dokumen, lalu setujui atau tolak dengan alasan. Keputusan tercatat di Log Audit.")
B.amf=new A.fd("Bagaimana menangani komplain pelanggan?","Buka menu Komplain, pilih komplain yang masih terbuka, lalu tindak lanjuti berdasarkan bukti dan riwayat pesanan. Tutup komplain setelah ada penyelesaian agar metrik layanan akurat.")
B.alU=new A.fd("Di mana memantau pembayaran dan webhook?","Menu Pembayaran menampilkan percobaan pembayaran terbaru beserta statusnya. Ops Alerts menandai pembayaran tertahan atau gagal sinkron, sehingga kamu bisa memeriksa gateway sebelum menyentuh data pesanan.")
B.am2=new A.fd("Apakah semua tindakan admin tercatat?","Ya. Perubahan status pesanan, pencairan, verifikasi, dan pengaturan platform dicatat di Log Audit beserta aktornya. Gunakan log ini saat menelusuri selisih data atau keluhan mitra.")
B.alZ=new A.fd("Bagaimana mengubah komisi dan voucher?","Komisi diatur di menu Komisi & Fee, sedangkan voucher di menu Voucher. Perubahan berlaku untuk transaksi berikutnya; transaksi yang sudah tercatat tetap memakai pengaturan saat itu.")
B.bdP=s([B.amh,B.ame,B.amf,B.alU,B.am2,B.alZ],t.vW)
B.amk=new A.C6("Admin","Rujukan operasional platform: pencairan mitra, verifikasi, komplain, dan pemantauan pembayaran.",B.bdP,"Buka Ops Alerts","/admin-ops-alerts","Alerts menandai hal yang butuh keputusan admin, termasuk pembayaran yang tertahan.")
B.bhI=new A.cu([B.HL,B.HK,B.HM,B.ami,B.HN,B.amj,B.HO,B.amk],A.aw("cu<C5,C6>"))
